-- Paket data awal dashboard PESTA, sumber BPS. Tidak memuat kredensial.
-- Backup dahulu. Pastikan migration 0010/0011 sudah diterapkan.
-- Periksa SELECT VERSION() dan ID SUPERADMIN di database tujuan.
-- Dataset yang sudah mempunyai versi tidak diubah. Aman diulang.
SET NAMES utf8mb4;
START TRANSACTION;
SET @pesta_reviewer = (SELECT id FROM users WHERE id = 1 AND role = 'SUPERADMIN' LIMIT 1);

-- Jumlah Penduduk
SET @pesta_dataset = (SELECT id FROM beregam_datasets WHERE kode = 'PENDUDUK_TOTAL' LIMIT 1);
SELECT id FROM beregam_datasets WHERE id = @pesta_dataset FOR UPDATE;
SET @pesta_import = (@pesta_reviewer IS NOT NULL AND @pesta_dataset IS NOT NULL AND NOT EXISTS (SELECT 1 FROM beregam_dataset_versions WHERE dataset_id = @pesta_dataset));
UPDATE beregam_datasets SET nama='Jumlah Penduduk',definisi='Jumlah penduduk Kabupaten Musi Rawas berdasarkan proyeksi hasil Sensus Penduduk. Angka sumber disajikan dalam ribu jiwa.',tema='Kependudukan',satuan='Ribu jiwa',source_type='manual',source_url='https://musirawaskab.bps.go.id/id/statistics-table/3/WVc0MGEyMXBkVFUxY25KeE9HdDZkbTQzWkVkb1p6MDkjMw%3D%3D/population-by-age-groups-and-sex--thousand--in-musi-rawas-regency--2023.html',sync_enabled=0,default_view='number',is_featured=1,featured_order=1,highlight_title='Jumlah Penduduk',highlight_note='Proyeksi penduduk hasil Sensus Penduduk.',is_active=1,updated_at=UTC_TIMESTAMP(3) WHERE id=@pesta_dataset AND @pesta_import=1;
SET @pesta_version = (SELECT id FROM beregam_dataset_versions WHERE dataset_id=@pesta_dataset AND content_hash='0d5e26f0a0d5f16559099dd62e78fff3343710e5f24e101e5b7106c0ccdbe8d0' LIMIT 1);
UPDATE beregam_indikator SET verified_by=@pesta_reviewer,updated_at=UTC_TIMESTAMP(3) WHERE version_id=@pesta_version AND @pesta_import=1;
UPDATE beregam_dataset_versions SET status='published',reviewed_at=UTC_TIMESTAMP(3),reviewed_by=@pesta_reviewer,review_note='Publikasi paket awal atas permintaan pemilik PESTA. Sumber diperiksa 2026-10-29; periode dan satuan dipertahankan.' WHERE id=@pesta_version AND @pesta_import=1;

