COMMIT;
SELECT d.kode,d.nama,v.status,COUNT(i.id) AS observasi FROM beregam_datasets d LEFT JOIN beregam_dataset_versions v ON v.dataset_id=d.id AND v.status='published' LEFT JOIN beregam_indikator i ON i.version_id=v.id AND i.verified_by IS NOT NULL WHERE d.kode IN ('PENDUDUK_TOTAL','PENDUDUK_JK','PENDUDUK_UMUR','MISKIN_TOTAL','MISKIN_PERSEN') GROUP BY d.id,d.kode,d.nama,v.status;
