INSERT INTO site_settings (setting_key,setting_value,grup,updated_by,created_at,updated_at) SELECT 'tampilan.dashboard','true','tampilan',@pesta_reviewer,UTC_TIMESTAMP(3),UTC_TIMESTAMP(3) WHERE @pesta_reviewer IS NOT NULL AND (SELECT COUNT(DISTINCT d.kode) FROM beregam_datasets d JOIN beregam_dataset_versions v ON v.dataset_id=d.id AND v.status='published' WHERE d.is_active=1 AND d.kode IN ('PENDUDUK_TOTAL','PENDUDUK_JK','PENDUDUK_UMUR','MISKIN_TOTAL','MISKIN_PERSEN'))=5 ON DUPLICATE KEY UPDATE setting_value='true',updated_by=@pesta_reviewer,updated_at=UTC_TIMESTAMP(3);
